# Portfolio: no hole, seven images fill four visual rows (first spans two rows)
rep(".tn22-photo:nth-child(1){grid-row:span 2}.tn22-photo:nth-child(6){grid-column:span 2;height:150px}",
    ".tn22-photo:nth-child(1){grid-row:span 2}", 'portfolio layout')

# Services styles: warmer background, pill category rail, fixed menu button, separate cards
service_css="""#tn13Services{margin:0!important;padding:0!important;background:#5a504a!important;color:#f5eee7!important;overflow:hidden!important}.tn22-services{padding:44px 18px 42px}.tn22-services .tn22-kicker{color:#d5cac1}.tn22-services h2{font-size:42px;color:#fff;white-space:nowrap}.tn23-tabbar{position:relative;margin-top:28px;padding-right:54px}.tn22-tabs{display:flex;gap:8px;overflow-x:auto;scrollbar-width:none;padding:0 2px}.tn22-tabs::-webkit-scrollbar{display:none}.tn22-tab{flex:0 0 auto;height:46px;padding:0 18px;border:1px solid rgba(255,255,255,.2);border-radius:999px;background:#f7f5f2;color:#272321;font:500 11.5px/1 'Manrope',Arial,sans-serif;white-space:nowrap}.tn22-tab.active{background:#111;color:#fff!important;border-color:#111}.tn23-cat-menu{position:absolute;z-index:4;right:0;top:0;width:46px;height:46px;border:1px solid rgba(40,34,31,.16);border-radius:50%;background:#fff;color:#171513;box-shadow:0 6px 18px rgba(30,24,21,.16);display:grid;place-items:center}.tn23-cat-menu svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round}.tn23-cat-pop{position:absolute;z-index:5;right:0;top:53px;width:176px;padding:7px;border:1px solid rgba(44,36,32,.14);border-radius:14px;background:#faf8f5;box-shadow:0 14px 36px rgba(34,27,24,.22);display:none}.tn23-cat-pop.open{display:grid}.tn23-cat-pop button{height:38px;border:0;border-radius:9px;background:transparent;color:#292522;text-align:left;padding:0 10px;font:500 11px/1 'Manrope',Arial,sans-serif}.tn23-cat-pop button.active{background:#111;color:#fff!important}.tn22-service-list{display:grid;gap:10px;margin-top:20px;border:0}.tn22-service{display:grid;grid-template-columns:minmax(0,1fr) 90px;gap:12px;padding:14px;border:1px solid rgba(255,255,255,.14);border-radius:14px;background:rgba(255,255,255,.055);align-items:center}.tn22-service-name{font:500 16px/1.18 'Cormorant Garamond',Georgia,serif;color:#fff}.tn22-service-desc{margin-top:7px;font:400 10.5px/1.48 'Manrope',Arial,sans-serif;color:#d2c7bf}.tn22-service-desc .clip{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.tn22-more{border:0;background:none;color:#f0d0ad;padding:0 0 0 4px;font-size:10px;text-decoration:underline;text-underline-offset:2px}.tn22-service-side{text-align:right;min-width:0}.tn22-price{font:500 15px/1 'Cormorant Garamond',Georgia,serif;color:#f0d0ad}.tn22-book-mini{width:88px;height:32px;margin-top:9px;padding:0 3px;border:1px solid rgba(241,220,197,.38);border-radius:8px;background:#171411;color:#fff!important;font:500 9px/1 'Manrope',Arial,sans-serif;white-space:nowrap}.tn22-show-services{width:100%;height:46px;margin-top:18px;border:1px solid rgba(241,220,197,.3);border-radius:11px;background:rgba(255,255,255,.04);color:#fff;font:500 11px/1 'Manrope',Arial,sans-serif}"""
s,n=re.subn(r"#tn13Services\{.*?\.tn22-show-services\{.*?\}\n\n#tn13Team",service_css+"\n\n#tn13Team",s,count=1,flags=re.S)
if n!=1: raise SystemExit('services css block not replaced')

# Review tracks: JS-driven, slower and draggable
