# Viewer like Nonna/Tahmina: no expand button, clean frame and footer
viewer_css=""".tn22-viewer{position:fixed;z-index:180;inset:0;display:none;align-items:center;justify-content:center;padding:22px;background:rgba(27,20,20,.9);backdrop-filter:blur(9px)}.tn22-viewer.open{display:flex}.tn22-viewer-frame{position:relative;width:min(100%,520px);height:min(82dvh,720px);background:transparent;overflow:visible;touch-action:none}.tn23-viewer-hint{position:absolute;z-index:4;top:-42px;left:0;color:rgba(255,255,255,.65);font:400 10px/1 'Manrope',Arial,sans-serif}.tn22-viewer-img{position:absolute;left:0;right:0;top:50%;width:100%;max-height:72%;transform:translateY(-50%);object-fit:contain;border-radius:10px;background:#151312;box-shadow:0 18px 54px rgba(0,0,0,.28);transform-origin:center center}.tn22-viewer-top{position:absolute;z-index:5;top:-52px;left:0;right:0;display:flex;justify-content:flex-end}.tn22-viewer-actions{display:flex}.tn22-vbtn{width:42px;height:42px;border:1px solid rgba(255,255,255,.22);border-radius:50%;background:rgba(255,255,255,.08);color:#fff!important;font-size:22px}.tn22-navbtn{position:absolute;z-index:5;top:50%;transform:translateY(-50%);width:30px;height:52px;border:0;background:transparent;color:#fff!important;font-size:35px;line-height:1}.tn22-prev{left:-5px}.tn22-next{right:-5px}.tn22-navbtn[hidden]{display:none!important}.tn23-viewer-foot{position:absolute;z-index:5;left:0;right:0;bottom:-34px;display:flex;align-items:center;justify-content:space-between;color:rgba(255,255,255,.68);font:400 10px/1 'Manrope',Arial,sans-serif}.tn22-viewer-count{font:500 10px/1 'Manrope',Arial,sans-serif;color:#fff}"""
s,n=re.subn(r"\.tn22-viewer\{.*?\.tn22-navbtn\[hidden\]\{display:none!important\}",viewer_css,s,count=1,flags=re.S)
if n!=1: raise SystemExit('viewer css block not replaced')

# Master page continuous profile sections
master_extra=""".tn23-master-stack{display:grid;gap:12px;margin-top:22px}.tn23-master-section{padding:17px;border:1px solid rgba(61,49,43,.1);border-radius:14px;background:rgba(255,255,255,.62)}.tn23-master-section h3{margin:0 0 11px;font:500 27px/1 'Cormorant Garamond',Georgia,serif}.tn23-master-empty{margin:0;color:#82776f;font:400 12px/1.5 'Manrope',Arial,sans-serif}.tn23-master-review{padding-top:10px;margin-top:10px;border-top:1px solid rgba(61,49,43,.08)}.tn23-master-review:first-of-type{padding-top:0;margin-top:0;border-top:0}.tn23-master-review strong{font:500 16px/1 'Cormorant Garamond',Georgia,serif}.tn23-master-review p{margin:6px 0 0;color:#514943;font:400 11px/1.5 'Manrope',Arial,sans-serif}"""
