# No hero autoplay. Manual swipe changes photo; tap opens salon gallery.
old_auto="let slide=0; const slides=[...hero.querySelectorAll('.tn22-slide')],dots=[...hero.querySelectorAll('.tn22-dots i')]; setInterval(()=>{slide=(slide+1)%slides.length;slides.forEach((x,i)=>x.classList.toggle('active',i===slide));dots.forEach((x,i)=>x.classList.toggle('active',i===slide));},4800);"
new_auto="""let slide=0; const slides=[...hero.querySelectorAll('.tn22-slide')],dots=[...hero.querySelectorAll('.tn22-dots i')];
function setHeroSlide(i){slide=(i+slides.length)%slides.length;slides.forEach((x,j)=>x.classList.toggle('active',j===slide));dots.forEach((x,j)=>x.classList.toggle('active',j===slide));}
const heroMedia=hero.querySelector('.tn22-media');let heroStartX=0,heroMoved=false;
heroMedia.addEventListener('pointerdown',e=>{heroStartX=e.clientX;heroMoved=false});
heroMedia.addEventListener('pointermove',e=>{if(Math.abs(e.clientX-heroStartX)>12)heroMoved=true});
heroMedia.addEventListener('pointerup',e=>{const dx=e.clientX-heroStartX;if(Math.abs(dx)>42){setHeroSlide(slide+(dx<0?1:-1));return}if(!heroMoved)openGallery('Салон')});"""
rep(old_auto,new_auto,'hero autoplay')

# Viewer markup and behavior
old_viewer="const viewer=document.createElement('div');viewer.className='tn22-viewer';viewer.innerHTML=`<div class=\"tn22-viewer-frame\"><div class=\"tn22-viewer-top\"><span class=\"tn22-viewer-count\">1 / 1</span><div class=\"tn22-viewer-actions\"><button class=\"tn22-vbtn tn22-expand\" type=\"button\" aria-label=\"Расширить\">↗</button><button class=\"tn22-vbtn tn22-view-close\" type=\"button\" aria-label=\"Закрыть\">×</button></div></div><img class=\"tn22-viewer-img\" alt=\"\"><button class=\"tn22-navbtn tn22-prev\" type=\"button\">‹</button><button class=\"tn22-navbtn tn22-next\" type=\"button\">›</button></div>`;root.appendChild(viewer);"
new_viewer="const viewer=document.createElement('div');viewer.className='tn22-viewer';viewer.innerHTML=`<div class=\"tn22-viewer-frame\"><div class=\"tn23-viewer-hint\">Разведите двумя пальцами, чтобы увеличить</div><div class=\"tn22-viewer-top\"><div class=\"tn22-viewer-actions\"><button class=\"tn22-vbtn tn22-view-close\" type=\"button\" aria-label=\"Закрыть\">×</button></div></div><img class=\"tn22-viewer-img\" alt=\"\"><button class=\"tn22-navbtn tn22-prev\" type=\"button\">‹</button><button class=\"tn22-navbtn tn22-next\" type=\"button\">›</button><div class=\"tn23-viewer-foot\"><span class=\"tn23-viewer-label\">Фото STLuxe</span><span class=\"tn22-viewer-count\">01 / 01</span></div></div>`;root.appendChild(viewer);"
