rep("vCount.textContent=`${viewerIndex+1} / ${viewerItems.length}`;", "vCount.textContent=`${String(viewerIndex+1).padStart(2,'0')} / ${String(viewerItems.length).padStart(2,'0')}`;vImg.style.transform='translateY(-50%) scale(1)';viewerScale=1;", 'viewer count')
rep("function closeViewer(){viewer.classList.remove('open');vFrame.classList.remove('zoom');if(!$('#tn13Gallery').classList.contains('open')&&!masterPage.classList.contains('open'))document.body.style.overflow=''}", "function closeViewer(){viewer.classList.remove('open');vImg.style.transform='translateY(-50%) scale(1)';viewerScale=1;if(!$('#tn13Gallery').classList.contains('open')&&!masterPage.classList.contains('open'))document.body.style.overflow=''}", 'viewer close')
old_events="vPrev.onclick=()=>{viewerIndex=(viewerIndex-1+viewerItems.length)%viewerItems.length;paintViewer()};vNext.onclick=()=>{viewerIndex=(viewerIndex+1)%viewerItems.length;paintViewer()};viewer.querySelector('.tn22-expand').onclick=()=>vFrame.classList.toggle('zoom');viewer.querySelector('.tn22-view-close').onclick=closeViewer;viewer.addEventListener('click',e=>{if(e.target===viewer)closeViewer()});let sx=0;vFrame.addEventListener('touchstart',e=>sx=e.touches[0].clientX,{passive:true});vFrame.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-sx;if(Math.abs(dx)>45&&viewerItems.length>1)(dx<0?vNext:vPrev).click()},{passive:true});"
new_events="""vPrev.onclick=()=>{viewerIndex=(viewerIndex-1+viewerItems.length)%viewerItems.length;paintViewer()};vNext.onclick=()=>{viewerIndex=(viewerIndex+1)%viewerItems.length;paintViewer()};viewer.querySelector('.tn22-view-close').onclick=closeViewer;viewer.addEventListener('click',e=>{if(e.target===viewer)closeViewer()});let sx=0,viewerScale=1,pinchStart=0;
const pinchDist=e=>Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);
vFrame.addEventListener('touchstart',e=>{if(e.touches.length===2){pinchStart=pinchDist(e)}else if(e.touches.length===1){sx=e.touches[0].clientX}},{passive:true});
vFrame.addEventListener('touchmove',e=>{if(e.touches.length===2&&pinchStart){e.preventDefault();viewerScale=Math.max(1,Math.min(3,pinchDist(e)/pinchStart));vImg.style.transform=`translateY(-50%) scale(${viewerScale})`}},{passive:false});
vFrame.addEventListener('touchend',e=>{if(e.changedTouches.length===1&&viewerScale===1&&viewerItems.length>1){const dx=e.changedTouches[0].clientX-sx;if(Math.abs(dx)>45)(dx<0?vNext:vPrev).click()}if(e.touches.length<2)pinchStart=0},{passive:true});"""
rep(old_events,new_events,'viewer events')

# Gallery render includes empty category
old_rg="function renderGallery(){const items=GALLERY[galleryCat]||[];gallery.innerHTML=`<div class=\"tn22-gallery\"><div class=\"tn22-gallery-top\"><button class=\"tn22-gallery-back\" type=\"button\">←</button><div class=\"tn22-gallery-title\"><strong>Галерея</strong><span>STLuxe</span></div><div></div></div><div class=\"tn22-gallery-tabs\">${Object.keys(GALLERY).map(c=>`<button class=\"tn22-gallery-tab${c===galleryCat?' active':''}\" type=\"button\" data-gcat=\"${c}\">${c}</button>`).join('')}</div><div class=\"tn22-gallery-grid${galleryCat==='Салон'?' salon':''}\">${items.map((x,i)=>`<button class=\"tn22-gallery-tile\" type=\"button\" data-gi=\"${i}\"><img src=\"${x.src}\" alt=\"${x.alt}\"></button>`).join('')}</div></div>`;gallery.querySelector('.tn22-gallery-back').onclick=closeGallery;gallery.querySelectorAll('[data-gcat]').forEach(b=>b.onclick=()=>{galleryCat=b.dataset.gcat;renderGallery()});gallery.querySelectorAll('[data-gi]').forEach(b=>b.onclick=()=>openViewer(items,+b.dataset.gi));}"
new_rg="function renderGallery(){const items=GALLERY[galleryCat]||[];gallery.innerHTML=`<div class=\"tn22-gallery\"><div class=\"tn22-gallery-top\"><button class=\"tn22-gallery-back\" type=\"button\">←</button><div class=\"tn22-gallery-title\"><strong>Галерея</strong><span>STLuxe</span></div><div></div></div><div class=\"tn22-gallery-tabs\">${Object.keys(GALLERY).map(c=>`<button class=\"tn22-gallery-tab${c===galleryCat?' active':''}\" type=\"button\" data-gcat=\"${c}\">${c}</button>`).join('')}</div><div class=\"tn22-gallery-grid${galleryCat==='Салон'?' salon':''}\">${items.length?items.map((x,i)=>`<button class=\"tn22-gallery-tile\" type=\"button\" data-gi=\"${i}\"><img src=\"${x.src}\" alt=\"${x.alt}\"></button>`).join(''):'<div class=\"tn23-gallery-empty\">Фото ресниц пока не добавлены</div>'}</div></div>`;gallery.querySelector('.tn22-gallery-back').onclick=closeGallery;gallery.querySelectorAll('[data-gcat]').forEach(b=>b.onclick=()=>{galleryCat=b.dataset.gcat;renderGallery()});gallery.querySelectorAll('[data-gi]').forEach(b=>b.onclick=()=>openViewer(items,+b.dataset.gi));}"
rep(old_rg,new_rg,'gallery render')
