new_status="const txt=el.querySelector('.tn22-status-text');if(open){txt.textContent='Открыто до 20:00';el.className='tn22-status open'}else{txt.textContent=monday?'Закрыто до вт 10:00':'Закрыто до 10:00';el.className='tn22-status closed'}"
